import numpy as np

def masked_bc_nll(
    selected_log_probs: np.ndarray,
    mask: np.ndarray,
    reduction: str = "mean",
) -> float:
    lp = np.asarray(selected_log_probs, dtype=np.float64)
    m = np.asarray(mask)
    if lp.shape != m.shape:
        raise ValueError("shapes must match")
    if np.any((m != 0) & (m != 1)):
        raise ValueError("mask must be binary")
    active_count = int(m.sum())
    if active_count == 0:
        raise ValueError("empty active mask")
    total = float(np.where(m.astype(bool), -lp, 0.0).sum())
    if reduction == "sum":
        return total
    if reduction == "mean":
        return total / active_count
    raise ValueError("reduction must be 'mean' or 'sum'")
```

