import numpy as np

def _logsumexp(x, axis=-1):
    x = np.asarray(x, dtype=float)
    m = np.max(x, axis=axis, keepdims=True)
    return np.squeeze(m + np.log(np.exp(x - m).sum(axis=axis, keepdims=True)), axis=axis)

def cql_penalty(q_values, data_actions):
    q = np.asarray(q_values, dtype=float)
    if q.ndim == 1:
        q = q[None, :]
    a = np.asarray(data_actions, dtype=int)
    if a.ndim == 0:
        a = np.full(q.shape[0], int(a))
    return float(np.mean(_logsumexp(q) - q[np.arange(q.shape[0]), a]))

def expectile_loss(residuals, tau):
    u = np.asarray(residuals, dtype=float)
    if not 0 < tau < 1:
        raise ValueError
    return np.abs(tau - (u < 0)) * u ** 2

def iql_weights(advantages, beta, max_weight=100.0):
    a = np.asarray(advantages, dtype=float)
    return np.minimum(np.exp(np.minimum(beta * a, np.log(max_weight))), max_weight)
